INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '1', 'Verbposition in einfachen Sätzen', 'B2/C1', 'O verbo conjugado ocupa a posição II em orações declarativas principais.', 'Meine Schwester arbeitet seit zwei Jahren in Hamburg.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '2', 'Verbposition in Satzverbindungen', 'B2', 'Em orações coordenadas com und/aber/oder/denn/sondern, cada oração mantém sua própria posição verbal (V2).', 'Ich habe die Prüfung bestanden, aber ich bin trotzdem nervös.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '3', 'Position von Dativ- und Akkusativobjekt', 'B2', 'Com dois substantivos, Dativ vem antes de Akkusativ; com um pronome, o pronome vem primeiro.', 'Der Kellner bringt dem Gast die Rechnung. Er bringt sie ihm.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '4', 'Position der Angaben im Satz', 'B2', 'Ordem padrão dos complementos no Mittelfeld: temporal – kausal – modal – lokal (TeKaMoLo).', 'Sie fährt morgen wegen der Konferenz mit dem Zug nach Berlin.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '5', 'Informationen direkt zum Verb', 'B2', 'Complementos de duração/modo que se ligam diretamente ao verbo ficam no final do Mittelfeld.', 'Er hat gestern drei Stunden lang Klavier gespielt.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '6', 'Position von nicht', 'B2', 'Nicht nega o elemento específico posicionando-se logo antes dele, ou vai ao final para negar a oração toda.', 'Ich habe nicht das ganze Buch gelesen. Das habe ich nicht gesagt.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '7', 'Position von auch und Fokuspartikeln', 'C1', 'Partículas de foco (auch, sogar, nur) mudam de sentido conforme a posição em relação ao elemento focado.', 'Auch meine Mutter spricht Französisch. / Meine Mutter spricht auch Französisch.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('1. Wortpositionen im Satz', '8', 'Informationsverteilung im Satz', 'C1', 'Informação conhecida (Thema) tende a vir antes; informação nova (Rhema) tende ao final da oração.', 'Den Ring hat sie ihrem Freund geschenkt.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('2. Konjunktiv II', '9', 'Konjunktiv 2 der Gegenwart: Formen', 'B2', 'Forma-se com würde + infinitivo, ou direto do Präteritum (verbos fortes, com Umlaut quando possível).', 'Wenn ich mehr Zeit hätte, würde ich öfter Sport treiben.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('2. Konjunktiv II', '10', 'Konjunktiv 2 der Vergangenheit: Formen', 'B2/C1', 'Forma-se sempre com hätte/wäre + Partizip II — não existe würde no passado.', 'Wenn ich das gewusst hätte, wäre ich früher gekommen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('2. Konjunktiv II', '11', 'Höflichkeit, Vorschläge, Ratschläge und Vorwürfe', 'B2', 'Konjunktiv II suaviza pedidos, sugestões, conselhos e reprovações.', 'Könntest du bitte das Fenster schließen? Du hättest mich anrufen sollen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('2. Konjunktiv II', '12', 'Wünsche, irreale Wünsche und irreale Bedingungen', 'B2', 'Expressa desejos irreais (wenn nur/doch) e condições hipotéticas não cumpridas.', 'Wenn ich doch nur mehr Geduld hätte!', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('2. Konjunktiv II', '13', 'Irreale Vergleiche und irreale Folgen', 'B2/C1', 'Usa als (ob)/als wenn para comparações irreais e sodass/so...dass para consequências hipotéticas.', 'Er tut so, als ob er nichts wüsste.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('3. Passiv', '14', 'Passiv in allen Zeiten', 'B2/C1', 'Passiv de processo (Vorgangspassiv): werden + Partizip II, conjugado em qualquer tempo.', 'Der Vertrag wird morgen unterschrieben.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('3. Passiv', '15', 'Passiv mit Modalverben in allen Zeiten', 'B2/C1', 'Verbo modal + Partizip II + werden (no infinitivo), em qualquer tempo verbal.', 'Das muss noch heute erledigt werden.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('3. Passiv', '16', 'Alternativen zum Passiv', 'B2', 'sich lassen + Infinitiv, sein + zu + Infinitiv substituem o passivo com nuance de possibilidade.', 'Das Problem lässt sich leicht lösen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('3. Passiv', '17', 'Formen mit Passivbedeutung', 'C1', 'bekommen-Passiv e construções reflexivas expressam sentido passivo sem usar werden.', 'Er bekommt das Zeugnis überreicht.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('3. Passiv', '18', 'Passivsätze ohne Subjekt', 'C1', 'Passivo impessoal, sem sujeito gramatical, focando a ação em si.', 'Hier wird viel gelacht.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('3. Passiv', '19', 'Wann ist Passiv möglich, wann nicht?', 'C1', 'Nem todo verbo transitivo admite passivo pessoal — depende da valência e do sentido do verbo.', 'Er besitzt ein Haus. (sem passivo pessoal natural)', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '20', 'Wechselpräpositionen', 'B2', 'Regem Akkusativ (movimento, pergunta wohin?) ou Dativ (posição, pergunta wo?) conforme o contexto.', 'Er stellt das Buch in den Schrank. Das Buch steht im Schrank.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '21', 'Oft gebrauchte lokale Präpositionen', 'B2', 'Preposições espaciais de uso frequente e o caso que regem.', 'Sie wohnt bei ihren Eltern.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '22', 'Weitere lokale Präpositionen', 'B2', 'Preposições espaciais menos frequentes, em geral com Genitiv.', 'Das Auto steht innerhalb des Parkplatzes.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '23', 'Die wichtigsten temporalen Präpositionen', 'B2', 'Preposições temporais centrais: an, in, um, seit, für, vor, nach.', 'Am Montag um 18 Uhr treffen wir uns.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '24', 'Weitere temporale Präpositionen', 'B2', 'Preposições temporais adicionais, muitas com Genitiv (während, innerhalb).', 'Ab Montag bin ich wieder im Büro.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '25', 'Kausale Präpositionen', 'B2', 'Preposições que expressam causa: wegen, aufgrund, aus, vor (+ sentimento).', 'Er kam wegen des Staus zu spät.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '26', 'Präpositionen der Redewiedergabe und Referenz', 'C1', 'Preposições usadas para referenciar declarações/fontes de terceiros: laut, zufolge, gemäß.', 'Laut dem Bericht steigen die Preise weiter.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '27', 'Präpositionen mit verschiedenen Positionen', 'B2/C1', 'Algumas preposições podem vir antes ou depois do substantivo, com leve mudança de ênfase.', 'Er geht die Straße entlang. / Entlang der Straße stehen Bäume.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '28', '„Sprechende“ Präpositionen', 'C1', 'Preposições cujo sentido literal original ainda é reconhecível: zuliebe, mittels, anhand.', 'Anhand der Daten konnte er seine These belegen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '29', 'Bedeutungen von in, an, auf, über, unter, vor', 'C1', 'Sentidos figurados/abstratos dessas preposições, além do uso espacial básico.', 'Er steht seit Wochen unter Druck.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('4. Präpositionen', '30', 'Bedeutungen von um, bei, von, nach, aus, mit, zu', 'C1', 'Sentidos figurados/abstratos dessas preposições em contextos não espaciais.', 'Sie handelt aus tiefer Überzeugung.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('5. Verben, Adjektive, Nomen und ihre Ergänzungen', '31', 'Verben mit Nominativ, Akkusativ und Dativ', 'B2/C1', 'Verbos com complemento duplo (Dativ da pessoa + Akkusativ da coisa) e sua ordem padrão.', 'Ich frage dich, ob du mir helfen kannst.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('5. Verben, Adjektive, Nomen und ihre Ergänzungen', '32', 'Verben mit Genitiv', 'C1', 'Grupo pequeno e formal de verbos que regem Genitiv (sich erfreuen, verdächtigen).', 'Man verdächtigt ihn des Betrugs.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('5. Verben, Adjektive, Nomen und ihre Ergänzungen', '33', 'Verben, Nomen und Adjektive mit Präpositionen', 'B2', 'Regência preposicional fixa, muitas vezes imprevisível a partir do sentido.', 'Es kommt darauf an, wann du ankommst.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('5. Verben, Adjektive, Nomen und ihre Ergänzungen', '34', 'Verben, Adjektive und Nomen mit festen Präpositionen mit Akkusativ', 'B2', 'Lista de regências fixas que exigem Akkusativ depois da preposição.', 'Ich freue mich schon auf das Wochenende.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('5. Verben, Adjektive, Nomen und ihre Ergänzungen', '35', 'Verben, Adjektive und Nomen mit festen Präpositionen mit Dativ', 'B2', 'Lista de regências fixas que exigem Dativ depois da preposição.', 'Ich träume oft von einer Weltreise.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('6. Bildung der Zeiten', '36', 'Bildung der Vergangenheitszeiten', 'B2', 'Formação de Perfekt, Präteritum e Plusquamperfekt (Hilfsverb + Partizip II ou forma própria).', 'Das Glas ist zerbrochen, aber wer hat es zerbrochen?', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('6. Bildung der Zeiten', '37', 'Besondere Perfektformen: Modalverben und sehen, hören, lassen', 'B2/C1', 'No Perfekt, esses verbos usam o infinitivo (Doppelinfinitiv) no lugar do Partizip II.', 'Ich habe gestern früh nach Hause gehen müssen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('6. Bildung der Zeiten', '38', 'Gebrauch von Zeiten der Vergangenheit', 'B2', 'Perfekt predomina na fala cotidiana; Präteritum predomina na escrita e narrativa.', 'Gestern bin ich spät aufgestanden. — Oh, das wusste ich nicht!', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('6. Bildung der Zeiten', '39', 'Vermutung und Zukunft mit dem Futur', 'B2/C1', 'Futur I/II expressam tanto futuro quanto suposição sobre o presente ou passado.', 'Er wird jetzt wohl schon zu Hause sein.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('6. Bildung der Zeiten', '40', 'Überblick über die Zeiten im Deutschen', 'C1', 'Visão geral comparativa dos seis tempos verbais do alemão e como se relacionam entre si.', 'Bis nächstes Jahr wird er das Projekt abgeschlossen haben.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('7. Modalverben, lassen und (un)trennbare Verben', '41', 'Modalverben in der Grundbedeutung', 'B2', 'Sentido básico (objetivo) dos modais: capacidade, permissão, obrigação, vontade.', 'Ich kann heute leider nicht kommen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('7. Modalverben, lassen und (un)trennbare Verben', '42', 'Andere Bedeutung von Modalverben: Vermutungen über die Gegenwart', 'B2', 'Uso subjetivo dos modais para expressar suposição sobre o presente.', 'Er müsste jetzt eigentlich zu Hause sein.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('7. Modalverben, lassen und (un)trennbare Verben', '43', 'Andere Bedeutung von Modalverben: Vermutungen über die Vergangenheit', 'C1', 'Modal + Perfekt Infinitiv para expressar suposição sobre o passado.', 'Sie muss wohl zu Fuß gegangen sein.', 'Grammatik aktiv B2-C1 (Cornelsen)');
