INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('7. Modalverben, lassen und (un)trennbare Verben', '45', 'Trennbare und untrennbare Verben 1', 'B2/C1', 'Prefixos sempre separáveis (an-, auf-, mit-) vs. sempre inseparáveis (be-, ver-, ent-).', 'Er kommt heute später an. / Sie bekommt ein Geschenk.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('7. Modalverben, lassen und (un)trennbare Verben', '46', 'Trennbare und untrennbare Verben 2', 'C1', 'Prefixos que podem ser separáveis ou inseparáveis conforme o sentido (durch-, um-, über-).', 'Er umfährt den Baum. / Er fährt die Mülltonne um.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('8. Nomen, Artikel und Pronomen', '47', 'Genusregeln', 'B2', 'Regras parciais para prever o gênero gramatical a partir da forma ou do sentido da palavra.', 'Wörter auf -ung, -heit, -keit sind feminin.', 'Grammatik aktiv B2-C1 (Cornelsen)');
