INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('8. Nomen, Artikel und Pronomen', '49', 'Genitiv', 'B2/C1', 'Formação e usos do caso genitivo, cada vez mais restrito ao registro formal/escrito.', 'Die Farbe des Autos gefällt mir sehr.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('8. Nomen, Artikel und Pronomen', '50', 'n-Deklination', 'B2', 'Substantivos masculinos fracos recebem -(e)n em todos os casos, exceto Nominativ Singular.', 'Ich habe dem Studenten die Frage beantwortet.', 'Grammatik aktiv B2-C1 (Cornelsen)');
