INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('8. Nomen, Artikel und Pronomen', '52', 'Deklination der Indefinit- und Possessivpronomen', 'B2', 'Terminações dos pronomes indefinidos e possessivos conforme caso e gênero.', 'Hast du meinen Schlüssel gesehen?', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('8. Nomen, Artikel und Pronomen', '53', 'Indefinitpronomen für Menschen', 'B2/C1', 'man, jemand, niemand e suas (poucas) formas de declinação.', 'Man sollte immer pünktlich sein.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('8. Nomen, Artikel und Pronomen', '54', 'Indefinitpronomen für Menschen und Dinge', 'B2', 'einer/eins, welche, alle, etwas, nichts e seu uso como substitutos.', 'Ich habe leider keins mehr davon.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('9. Adjektive', '55', 'Adjektivdeklination', 'B2', 'Terminações do adjetivo atributivo conforme o tipo de artigo, caso e gênero.', 'Der alte Mann liest ein spannendes Buch.', 'Grammatik aktiv B2-C1 (Cornelsen)');
