INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('9. Adjektive', '58', 'Partizip I und II als Adjektiv', 'B2', 'Particípios usados como adjetivo atributivo, com sentido ativo (Partizip I) ou passivo (Partizip II).', 'das lachende Kind / der geöffnete Brief', 'Grammatik aktiv B2-C1 (Cornelsen)');
