INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('10. Indirekte Rede', '61', 'Wiedergabe von Aufforderungen, Gerüchten und Selbstaussagen', 'C1', 'Como reportar ordens, boatos e declarações de terceiros com sollen/wollen.', 'Er soll angeblich sehr reich sein.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '62', 'Temporale Nebensätze', 'B2', 'Conectores temporais: als, wenn, während, bevor, nachdem, seitdem, sobald.', 'Seitdem sie hier wohnt, ist alles viel einfacher.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '63', 'Kausale und konzessive Nebensätze', 'B2/C1', 'weil/da (causa) em contraste com obwohl/obgleich (concessão).', 'Obwohl es stark regnete, gingen wir spazieren.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '64', 'Konsekutive Nebensätze', 'B2/C1', 'Consequência com sodass ou so ... dass.', 'Es regnete so stark, dass wir zu Hause blieben.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '65', 'Konditionale und adversative Nebensätze', 'B2/C1', 'Condição com wenn/falls e contraste com während adversativo.', 'Falls es morgen regnet, bleiben wir einfach drinnen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '66', 'Modale Nebensätze (Methode)', 'B2/C1', 'Modo ou meio de realizar algo, com indem ou dadurch dass.', 'Er lernte Deutsch, indem er jeden Tag Filme ansah.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '67', 'Infinitiv mit und ohne zu', 'B2/C1', 'Verbos que exigem zu + Infinitiv, em contraste com os que não exigem (modais, sehen/hören/lassen).', 'Er hofft, die Prüfung dieses Mal zu bestehen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '68', 'Nebensatz mit dass und Infinitiv mit zu', 'B2', 'Quando usar oração com dass ou preferir a infinitiva reduzida (mesmo sujeito nas duas orações).', 'Ich hoffe, dass er kommt. / Ich hoffe, ihn bald zu sehen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '69', 'Finale und modale Infinitiv- und Nebensätze', 'B2', 'Finalidade expressa com um ... zu ou damit.', 'Er lernt jeden Tag, um die Prüfung zu bestehen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '70', 'Relativpronomen im Nominativ, Akkusativ und Dativ', 'B2/C1', 'Formação e uso do pronome relativo nesses três casos.', 'Das ist die Frau, der wir die Idee verdanken.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '71', 'Relativpronomen im Genitiv', 'B2/C1', 'Pronome relativo genitivo: dessen (masc./neutro) e deren (fem./plural).', 'Die Frau, deren Hund ständig bellt, ist meine Nachbarin.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('11. Nebensätze', '72', 'Relativpronomen mit w- und als', 'B2/C1', 'Relativas generalizantes com was/wer/wo/worüber, e comparativas com als.', 'Das ist genau das, was mich am meisten stört.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '73', 'Doppelkonnektoren', 'B2/C1', 'Conectores duplos: entweder ... oder, sowohl ... als auch, weder ... noch, nicht nur ... sondern auch.', 'Entweder wir gehen jetzt, oder wir bleiben ganz zu Hause.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '74', 'Negationswörter', 'B2', 'Palavras de negação além de nicht: nie, nirgends, niemand, kein, nichts.', 'Ich habe meine Schlüssel nirgends gefunden.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '75', 'Irgend…', 'B2', 'Composições com irgend- para indeterminação: irgendjemand, irgendwas, irgendwie, irgendwann.', 'Hat irgendjemand irgendetwas Verdächtiges gesehen?', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '76', 'Position und Direktion', 'B2', 'Advérbios de lugar/direção (hin/her) e o par de verbos stehen/stellen, liegen/legen etc.', 'Stell die Vase bitte auf den Tisch.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '77', 'Es', 'B2', 'Os múltiplos usos gramaticais de es: impessoal, expletivo, correlato de oração subordinada.', 'Es klopft schon wieder an der Tür.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '78', 'Funktionsverbgefüge 1', 'B2', 'Construções verbo-suporte de uso muito frequente: in Frage stellen, zur Verfügung stehen.', 'Wir müssen jetzt endlich eine Entscheidung treffen.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '79', 'Funktionsverbgefüge 2', 'C1', 'Construções verbo-suporte com nuance passiva/estativa: in Aufregung geraten, zum Ausdruck kommen.', 'Er gerät bei diesem Thema leicht in Aufregung.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '80', 'Wörter mit da-', 'B2', 'Pró-formas prepositivas: damit, dabei, dadurch, substituindo preposição + pronome/oração.', 'Ich habe lange hier gewohnt. Dabei wollte ich das nie.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('12. Besondere Wörter und Wortverbindungen', '81', 'Modalpartikeln', 'B2/C1', 'Partículas modais (doch, ja, eben, halt, mal, schon) que matizam a atitude do falante.', 'Das war doch von Anfang an klar!', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('13. Umformung von Sätzen', '82', 'Nominalisierung', 'C1', 'Transformar uma oração verbal em sintagma nominal — marca central do registro formal/nominal.', 'Durch die konsequente Nutzung von Nomen entsteht sprachliche Verdichtung.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('13. Umformung von Sätzen', '83', 'Links- und Rechtsattribute', 'C1', 'Atributo antes do substantivo (particípio estendido) vs. depois (oração relativa/preposição).', 'der von mir vor Kurzem gelesene Roman / der Roman, den ich vor Kurzem gelesen habe', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('13. Umformung von Sätzen', '84', 'Präposition – Adverb – Konnektor 1', 'C1', 'Equivalência entre preposição, advérbio conjuntivo e conector subordinativo no campo temporal.', 'vor dem Essen / vorher / bevor wir aßen', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('13. Umformung von Sätzen', '85', 'Präposition – Adverb – Konnektor 2', 'C1', 'Mesma equivalência no campo causal, consecutivo, concessivo e adversativo.', 'wegen des Regens / deshalb / weil es regnete', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('13. Umformung von Sätzen', '86', 'Präposition – Adverb – Konnektor 3', 'C1', 'Mesma equivalência no campo modal, condicional e final.', 'durch Übung / dadurch / indem man übt', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('14. Und noch mehr Wissenswertes', '87', 'Kommaregeln', 'B2', 'Regras de vírgula em orações subordinadas, enumerações, apostos e infinitivas.', 'Ich esse gern Fisch, Fleisch und Gemüse.', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('14. Und noch mehr Wissenswertes', '88', 'Besondere Formen der mündlichen Sprache', 'C1', 'Formas reduzidas e coloquiais da fala espontânea (haste, kommste, biste).', 'Da kommste ja endlich mal wieder an!', 'Grammatik aktiv B2-C1 (Cornelsen)');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('15. Wortbildung (complementar — PONS)', 'PONS', 'Nominalisierende Suffixe (-heit, -keit, -ung, -schaft, -tum)', 'Referência', 'Sufixos que transformam adjetivos ou verbos em substantivos abstratos femininos/neutros.', 'die Freiheit, die Möglichkeit, die Bildung, die Freundschaft', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('15. Wortbildung (complementar — PONS)', 'PONS', 'Adjektivbildende Suffixe (-bar, -lich, -ig, -isch, -los)', 'Referência', 'Sufixos que formam adjetivos a partir de verbos ou substantivos.', 'lesbar, freundlich, farbig, typisch, arbeitslos', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('15. Wortbildung (complementar — PONS)', 'PONS', 'Verbbildende Präfixe (be-, ver-, ent-, zer-, er-)', 'Referência', 'Prefixos que alteram o sentido e, frequentemente, a valência do verbo base.', 'besprechen, verstehen, entdecken, zerbrechen, erklären', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('15. Wortbildung (complementar — PONS)', 'PONS', 'Komposita (Nomen-Nomen, Adjektiv-Nomen etc.)', 'Referência', 'Regras de formação e de atribuição de gênero em substantivos compostos (o último elemento define o gênero).', 'die Fahrschule, der Hochsitz, das Wohnzimmer', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('15. Wortbildung (complementar — PONS)', 'PONS', 'Diminutive -chen/-lein', 'Referência', 'Sufixos diminutivos, sempre neutros, frequentemente com Umlaut na vogal da raiz.', 'das Häuschen, das Büchlein', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('16. Zahlwörter (complementar — PONS)', 'PONS', 'Kardinalzahlen und Ordinalzahlen', 'Referência', 'Números cardinais e ordinais, incluindo a declinação dos ordinais em contexto formal.', 'am dritten Mai, im zweiten Kapitel', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('16. Zahlwörter (complementar — PONS)', 'PONS', 'Brüche und Dezimalzahlen', 'Referência', 'Formação de frações e leitura de números decimais em alemão.', 'ein Drittel der Teilnehmer, zwei Komma fünf Prozent', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('17. Partikeln und Interjektionen (complementar — PONS)', 'PONS', 'Gradpartikeln (sehr, ziemlich, äußerst, kaum)', 'Referência', 'Partículas de grau que intensificam ou atenuam adjetivos e advérbios.', 'Das finde ich äußerst interessant.', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('17. Partikeln und Interjektionen (complementar — PONS)', 'PONS', 'Interjektionen und Satzäquivalente', 'Referência', 'Interjeições e expressões de uma palavra que substituem uma oração inteira na fala espontânea.', 'Ach so! Na klar. Schade, dass du nicht kommen kannst.', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('18. Rechtschreibung und Zeichensetzung (complementar — PONS)', 'PONS', 'Groß- und Kleinschreibung', 'Referência', 'Regras de maiúscula/minúscula: substantivos, adjetivos substantivados, início de citação direta.', 'Das Lesen macht mir schon seit Kindheit an Freude.', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('18. Rechtschreibung und Zeichensetzung (complementar — PONS)', 'PONS', 's, ss oder ß?', 'Referência', 'A grafia depende da duração da vogal precedente: vogal curta = ss, vogal longa/ditongo = ß.', 'das Wasser, der Fluss, die Straße, der Fuß', 'PONS Die große Grammatik Deutsch');
INSERT INTO content_topics (categoria, capitulo, topico, nivel, regra, exemplo, fonte) VALUES ('18. Rechtschreibung und Zeichensetzung (complementar — PONS)', 'PONS', 'Anführungszeichen, Doppelpunkt, Semikolon', 'Referência', 'Uso de aspas, dois-pontos e ponto e vírgula além das regras de vírgula.', 'Er sagte: „Ich komme heute leider später.“', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('1. Vokale', 'Kurze und lange Vokale', 'Alta', 'A duração da vogal muda o significado da palavra — não é só sotaque, é distintivo. Vogal longa geralmente = sílaba aberta ou seguida de uma só consoante; vogal curta = seguida de consoante dobrada ou grupo consonantal.', 'Staat [a:] (Estado) vs. Stadt [a] (cidade) — mesmo "a", duração diferente, palavra diferente.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('1. Vokale', 'Umlaute ä, ö, ü', 'Alta', 'Vogais anteriores arredondadas (ö, ü) não existem em português — a língua fica na posição de "i"/"e" mas os lábios arredondam como em "u"/"o".', 'schön (bonito) vs. schon (já); Mühle (moinho) vs. Mule/Mole.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('1. Vokale', 'Diphthonge ei/ai, äu/eu, au', 'Baixa', 'Mesma pronúncia para grafias diferentes — mais curiosidade ortográfica do que dificuldade de produção, já que você já produz esses ditongos corretamente.', 'Leib (corpo) e Laib (pão) são homófonos — mesma pronúncia, grafia e sentido diferentes.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('1. Vokale', 'e [e] vs. ä [ɛ] em fala cuidada', 'Média', 'Distinção fina entre "e" fechado e "ä" aberto, neutralizada em muitas regiões — vale conhecer mas não é erro grave misturar.', 'Bären (ursos) com [ɛ] vs. Beeren (frutas silvestres) com [e] — a diferença se perde em fala rápida no norte da Alemanha.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('2. Konsonanten', 'ich-Laut [ç] vs. ach-Laut [x]', 'Alta', 'O "ch" muda de som conforme a vogal anterior: depois de e/i soa "claro" (palatal); depois de a/o/u/au soa "escuro" (velar, mais gutural).', 'rechnen, mich, weich → [ç] (claro). wach, Rauch, Buch → [x] (escuro, mais gutural).', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('2. Konsonanten', 's-Laute: quando é [z] e quando é [s]', 'Média', '"S" no início de palavra/sílaba antes de vogal é sonoro [z]; "s", "ss" ou "ß" em outras posições é surdo [s]. A grafia ss/ß depende da duração da vogal anterior (curta = ss, longa/ditongo = ß).', 'Salz, Sonne (início, [z]) vs. Reis, Wasser, weiß (fim/dobrado, [s]).', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('2. Konsonanten', 'sp- e st- no início de palavra/sílaba', 'Média', 'Na pronúncia padrão, "sp"/"st" no início soam "schp"/"scht"; no meio ou fim da palavra soam "sp"/"st" normal.', 'Spitze, Steine → "schpitze schteine". Aber: Herbst, Fenster → "sp/st" normal.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('2. Konsonanten', 'Auslautverhärtung (b/d/g → p/t/k no final)', 'Alta', 'Consoantes sonoras b/d/g ficam surdas (p/t/k) no final de sílaba, mesmo sem mudança na grafia — isso não aparece escrito, só na fala.', 'Kalb soa como [kalp]; Bad soa como [ba:t]; Berg soa como [berk]. Mas: Kälber, Bäder, Berges voltam ao som sonoro.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('2. Konsonanten', 'r-Realisierung: Zäpfchen-r vs. Zungenspitzen-r', 'Alta', 'O "r" alemão padrão é uvular (produzido na garganta, tipo "gargarejo"), bem diferente do "r" vibrante/tepe do português. Escolha uma realização e seja consistente.', 'rennen, Straße — "r" uvular [ʁ], não o "r" batido do português.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('3. Der Knacklaut (golpe glótico)', 'O que é o Knacklaut', 'Alta', 'Uma breve interrupção nas cordas vocais antes de sílaba tônica que começa com vogal — dá a separação nítida entre palavras/sílabas que o alemão tem e o português não. Sua ausência é uma das marcas mais características de sotaque estrangeiro.', 'beachten [bəˈʔaxtn̩], die Uhr [diː ˈʔuːɐ̯] — a pausa antes do "a"/"U" é o Knacklaut.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('3. Der Knacklaut (golpe glótico)', 'Por que falantes de português tendem a não produzir', 'Alta', 'Português tende a ligar (fazer sinalefa) entre palavras/sílabas que terminam e começam com vogal; alemão faz o oposto — corta.', '"beinhalten" dito de um fôlego só (como em português) soa estrangeiro; com Knacklaut soa nativo: be-[ʔ]inhalten.', 'Pesquisa complementar');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('4. Silbenstruktur', 'Anlaut, Inlaut, Auslaut', 'Baixa', 'Nomenclatura pra posição do som dentro da sílaba/palavra (início, meio, fim) — útil só como vocabulário técnico pra entender as outras regras da tabela.', 'im Wort Hand: H- é Anlaut, -a- é Inlaut, -nd é Auslaut.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('4. Silbenstruktur', 'Offene und geschlossene Silben', 'Média', 'Sílaba aberta (termina em vogal) tende a ter vogal longa; sílaba fechada (termina em consoante) tende a ter vogal curta — ajuda a prever/checar a duração vocálica.', 'of-fen (sílaba fechada, "o" curto) vs. o-der (sílaba aberta, "o" longo).', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('5. Wortakzent', 'Acento em palavras de 2 sílabas', 'Média', 'Palavras alemãs nativas de 2 sílabas acentuam a primeira; muitos empréstimos de outras línguas acentuam a segunda.', '''Wetter, ''spielen (nativa, 1ª sílaba) vs. Kar''ton, Kon''flikt (empréstimo, 2ª sílaba).', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('5. Wortakzent', 'Acento em palavras de 3+ sílabas', 'Média', 'Tende a cair na penúltima sílaba, com uma sílaba de acento secundário nas palavras mais longas.', 'Ba''nane, Regierung → acento na penúltima; unmissver''ständlich tem acento principal e secundário.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('5. Wortakzent', 'Acento em palavras compostas (Komposita)', 'Alta', 'No composto, o PRIMEIRO elemento carrega o acento principal — erro comum de quem tenta acentuar como no português (geralmente o núcleo por último).', '''Taschenrechner (calculadora) — acento em "Ta-", não em "-rechner".', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('5. Wortakzent', 'Acento em verbos com prefixo separável vs. inseparável', 'Alta', 'Prefixos SEPARÁVEIS carregam o acento (ligado ao seu tópico gramatical de trennbare Verben); prefixos INSEPARÁVEIS nunca são acentuados.', '''aufstehen, ''weggehen (separável, acento no prefixo) vs. ver''stehen, be''kommen (inseparável, acento na raiz).', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('6. Satzmelodie und Intonation', 'Fallende Intonation (afirmações e perguntas-Wh)', 'Alta', 'A entonação cai no final de frases afirmativas e perguntas com palavra interrogativa (was, wer, wo...) — sinaliza "fechamento", útil pra soar assertivo no Speech.', 'Wir gehen heute ins Kino. ↘ / Wo warst du gestern? ↘', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('6. Satzmelodie und Intonation', 'Steigende Intonation (perguntas sim/não)', 'Alta', 'A entonação sobe no final de perguntas sem palavra interrogativa — inclusive pode transformar uma afirmação em pergunta SÓ pela entonação, sem mudar a ordem das palavras.', 'Wir gehen heute ins Kino? ↗ (mesma frase da afirmação acima, só muda a entonação)', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('6. Satzmelodie und Intonation', 'Satzakzent / Fokusakzent (ênfase contrastiva)', 'Alta', 'Qual palavra recebe o acento mais forte na frase muda o que está sendo destacado/contrastado — conecta direto com seu tópico gramatical de Fokuspartikeln e Informationsverteilung.', 'ICH habe das nicht gesagt. (não eu) vs. Ich habe das NICHT gesagt. (não disse)', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('7. Regionale Aussprachevarianten', 'Hochdeutsch vs. Mundarten', 'Baixa', 'Não existe uma "pronúncia padrão" única e oficial — a referência prática de hoje é a fala de apresentadores de telejornal, mas há variação regional legítima (Norddeutsch, Süddeutsch, Österreich, Schweiz).', 'Tag pode soar "Tach" [tax] no norte; r pode ser uvular ou "rolado" (alveolar) conforme a região.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('7. Regionale Aussprachevarianten', 'Reconhecer variantes sem precisar produzi-las', 'Baixa', 'Pra compreensão (que já não é seu gargalo), vale reconhecer essas variantes; pra produção, escolha e mantenha uma pronúncia consistente (a de telejornal é a aposta mais segura).', 'Não é necessário "escolher um sotaque regional" — mantenha a pronúncia-padrão como referência de produção.', 'PONS Die große Grammatik Deutsch');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('8. Pontos de atenção específicos (falante de português)', 'Sinalefa vs. Knacklaut', 'Alta', 'Português junta/liga vogais entre palavras (sinalefa); alemão faz o oposto e corta com o Knacklaut. É provavelmente o ajuste de produção com maior retorno pra soar nativo.', '"em_alto_e_bom_som" (liga) vs. "be-[ʔ]achten" (corta) — hábito oposto ao do português.', 'Pesquisa complementar');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('8. Pontos de atenção específicos (falante de português)', 'R uvular vs. R vibrante/tepe do português', 'Alta', 'O r do português (batido ou retroflexo conforme a região do Brasil) não existe em alemão — o padrão é uvular, na garganta.', 'rennen, Straße — praticar a posição de "gargarejo" leve pra sentir onde o som se forma.', 'Pesquisa complementar');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('8. Pontos de atenção específicos (falante de português)', 'Distinção de duração vocálica (curta/longa)', 'Alta', 'Português não usa duração da vogal pra distinguir palavras da mesma forma que o alemão — esse é um eixo fonológico novo, não só uma questão de sotaque.', 'Staat/Stadt, Beet/Bett — pares mínimos que só existem por causa da duração da vogal.', 'Pesquisa complementar');
INSERT INTO phonetic_points (categoria, topico, prioridade, descricao, exemplo, fonte) VALUES ('8. Pontos de atenção específicos (falante de português)', 'Consoantes finais sonoras que na fala ficam surdas', 'Média', 'Ligado à Auslautverhärtung — em português quase todas as consoantes finais já soam "fechadas"; em alemão o padrão é sistemático e vale a pena internalizar como regra, não caso a caso.', 'Tag [ta:k], nicht [taːg] — mesmo terminando em "g" na escrita, o som final é [k].', 'Pesquisa complementar');
